SELECT CASE WHEN c.credit_limit >= 15700 THEN 'high' WHEN c.credit_limit >= 5700 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, c.is_active, MAX(a.balance) AS max_balance, MIN(a.opened_date) AS first_opened_date FROM accounts a LEFT JOIN customers c ON a.customer_id = c.id WHERE a.status IS NOT NULL GROUP BY CASE WHEN c.credit_limit >= 15700 THEN 'high' WHEN c.credit_limit >= 5700 THEN 'mid' ELSE 'low' END, c.is_active
